<script>
(function(){
const registry=<?= $registryJson ?>;let widgets=<?= $initialJson ?>;const builderCountries=<?= $builderCountriesJson ?>,builderCities=<?= $builderCitiesJson ?>,builderCategories=<?= $builderCategoriesJson ?>;let selected=null;let dragIndex=null;
let previewTimer=null,previewSequence=0;
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(updatePreview,350)}
function updatePreview(){
 const seq=++previewSequence;$('pbPreviewStatus').textContent='Önizleme güncelleniyor…';
 const data=new URLSearchParams();data.set('_csrf',$('pbForm').querySelector('[name="_csrf"]').value);data.set('theme',$('pbTheme').value);data.set('page',$('pbPage').value);data.set('layout_json',JSON.stringify({widgets}));
 fetch('<?= e(app_url('/admin/builder/preview')) ?>',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:data.toString()})
 .then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.text()})
 .then(()=>{if(seq!==previewSequence)return;const previewBase=$('pbPage').value==='home'?'<?= e(app_url('/')) ?>':'<?= e(app_url('/page/')) ?>'+encodeURIComponent($('pbPage').value);$('pbPreviewFrame').src=previewBase+'?builder_preview=1&v='+Date.now();$('pbPreviewStatus').textContent='Canlı önizleme güncel';})
 .catch(()=>{if(seq===previewSequence)$('pbPreviewStatus').textContent='Önizleme alınamadı · Oturumunuzu kontrol edin';});
}

const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fieldsFor(w){const common=[['title','Başlık','text'],['subtitle','Alt başlık','text'],['description','Açıklama','textarea']];const hero=[['eyebrow','Üst kısa başlık','text'],...common,['image_url','Arka plan görsel URL','url'],['hero_layout','Hero yerleşimi','select:overlay,split,minimal'],['hero_text_position','Metin konumu','select:left,center,right'],['show_search','Arama motorunu göster','select:1,0'],['search_position','Arama motoru konumu','select:below,left,right,inside-bottom'],['search_layout','Arama motoru düzeni','select:horizontal,vertical'],['hero_height','Hero yüksekliği (px)','number'],['overlay_opacity','Görsel karartma (%)','number'],['button_text','Buton metni','text'],['button_url','Buton bağlantısı','text']];const search=[...common,['location_placeholder','Konum alanı ipucu','text'],['button_text','Arama butonu metni','text'],['search_layout','Arama motoru düzeni','select:horizontal,vertical'],['search_columns','Arama kolon sayısı','number']];const cards=[...common,['columns','Kolon sayısı','number'],['limit','Gösterilecek kayıt','number']];const media=[...common,['image_url','Görsel URL','url'],['button_text','Buton metni','text'],['button_url','Buton bağlantısı','text']];if(w.type==='hero')return hero;if(['search','property_search','booking_cta'].includes(w.type))return search;if(['properties','featured','recent_properties','popular_properties'].includes(w.type))return [...cards,['sort_by','Sıralama','select:recent,popular,price_low,price_high,rating'],['location_id','Şehir filtresi','city'],['category_id','Kategori filtresi','category'],['min_guests','Minimum misafir','number'],['min_price','Minimum gecelik fiyat','number'],['max_price','Maksimum gecelik fiyat','number'],['min_rating','Minimum puan (10 üzerinden)','number'],['show_location','Konumu göster','select:1,0'],['show_guests','Misafir kapasitesini göster','select:1,0'],['show_price','Gecelik fiyatı göster','select:1,0'],['show_rating','Puanı göster','select:1,0'],['show_review_count','Yorum sayısını göster','select:1,0'],['show_gallery','Kartta fotoğraf galerisi','select:1,0'],['show_favorite','Favori kalp simgesi','select:1,0'],['show_badges','Puan rozeti','select:1,0'],['image_ratio','Görsel oranı,'select:4:3,1:1,3:2,16:9,portrait'],['empty_message','Sonuç yok mesajı','text']];if(['destinations','location_cards'].includes(w.type))return [...cards,['sort_by','Sıralama','select:popular,alphabetical'],['country_id','Ülke filtresi','country'],['show_property_count','Konaklama sayısını göster','select:1,0'],['image_ratio','Görsel oranı','select:4:3,1:1,3:2,16:9,portrait'],['empty_message','Sonuç yok mesajı','text']];if(w.type==='seasonal')return [...cards,['eyebrow','Sezon etiketi','text'],['sort_by','Sıralama','select:popular,recent,price_low,price_high,rating'],['location_id','Şehir filtresi','city'],['category_id','Kategori filtresi','category'],['min_guests','Minimum misafir','number'],['min_price','Minimum gecelik fiyat','number'],['max_price','Maksimum gecelik fiyat','number'],['image_ratio','Görsel oranı','select:4:3,1:1,3:2,16:9,portrait'],['empty_message','Sonuç yok mesajı','text']];if(w.type==='categories')return [...common,['sort_by','Sıralama','select:popular,alphabetical'],['show_property_count','Konaklama sayısını göster','select:1,0'],['empty_message','Sonuç yok mesajı','text'],['columns','Kolon sayısı','number'],['limit','Kategori sayısı','number']];if(['testimonials','review_summary'].includes(w.type))return [...common,['limit','Gösterilecek yorum','number'],['columns','Kolon sayısı','number']];if(w.type==='hosts')return [...common,['limit','Gösterilecek ev sahibi','number'],['columns','Kolon sayısı','number']];if(['image','gallery','image_text','banner','promo','cta'].includes(w.type))return [['eyebrow','Üst kısa başlık','text'],...media];if(['testimonials','features','services','faq','stats','trust','steps','amenities','nearby','timeline','icon_list','team','awards','logos','blog','pricing','social'].includes(w.type))return [...common,['items_text',w.type==='pricing'?'Paketler (Ad|Fiyat|Açıklama)':(w.type==='blog'?'Yazılar (Başlık|Özet|Bağlantı)':(w.type==='social'?'Sosyal bağlantılar (Ad|URL)':'Öğe listesi (her satıra bir öğe; Soru|Cevap veya Etiket|Değer)')),'textarea'],['columns','Kolon sayısı','number']];if(w.type==='video')return [...common,['video_url','YouTube veya Vimeo bağlantısı','url'],['image_url','Kapak görseli URL','url']];if(w.type==='map')return [...common,['map_query','Harita konumu / adres','text']];if(w.type==='contact')return [...common,['contact_phone','Telefon','text'],['contact_email','E-posta','email'],['contact_address','Adres','textarea'],['button_text','Buton metni','text'],['button_url','Buton bağlantısı','text']];if(w.type==='newsletter')return [...common,['contact_email','Abonelik iletişim e-postası','email'],['button_text','Buton metni','text']];if(w.type==='countdown')return [...common,['target_date','Hedef tarih (YYYY-MM-DDTHH:MM)','text']];return [...common,['eyebrow','Üst kısa başlık','text'],['alignment','Metin hizası','select:left,center,right'],['button_text','Buton metni','text'],['button_url','Buton bağlantısı','text']]}
function renderPalette(filter=''){const root=$('pbPalette');root.innerHTML='';const groups={};Object.values(registry).forEach(w=>{if(filter&&!w.label.toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr'))&&!w.category.toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')))return;(groups[w.category]??=[]).push(w)});Object.keys(groups).forEach(group=>{const section=document.createElement('section');section.className='pb-group';section.innerHTML='<div class="pb-group-title">'+esc(group)+'</div>';groups[group].forEach(w=>{const b=document.createElement('button');b.type='button';b.className='pb-widget';b.draggable=true;b.dataset.type=w.type;b.innerHTML='<span class="ico">＋</span><span>'+esc(w.label)+'<small>'+w.styles.length+' stil seçeneği</small></span>';b.addEventListener('click',()=>addWidget(w.type));b.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',w.type);e.dataTransfer.effectAllowed='copy'});section.appendChild(b)});root.appendChild(section)})}
function addWidget(type,index=widgets.length){const w=registry[type];if(!w)return;const item={id:'w'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),type,style:w.default_style,settings:{title:w.label}};widgets.splice(index,0,item);selected=item.id;render()}
function render(){const root=$('pbBlocks');root.innerHTML='';widgets.forEach((w,i)=>{const meta=registry[w.type];if(!meta)return;const card=document.createElement('article');card.className='pb-block'+(selected===w.id?' selected':'');card.draggable=true;card.dataset.index=i;const title=w.settings?.title||meta.label;card.innerHTML='<div class="pb-block-head"><span class="pb-grip">⠿</span><span class="pb-block-title">'+esc(title)+'</span><span class="pb-block-type">'+esc(meta.label)+' · '+esc(w.style)+'</span><span class="pb-block-actions"><button type="button" data-up>↑</button><button type="button" data-down>↓</button><button type="button" data-copy>⧉</button><button type="button" data-delete>×</button></span></div><div class="pb-block-preview"><strong>'+esc(title)+'</strong><span>'+esc(w.settings?.subtitle||meta.label+' widget alanı · '+w.style+' görünümü')+'</span></div>';card.addEventListener('click',e=>{if(e.target.closest('button'))return;selected=w.id;render()});card.addEventListener('dragstart',()=>{dragIndex=i;card.classList.add('dragging')});card.addEventListener('dragend',()=>card.classList.remove('dragging'));card.addEventListener('dragover',e=>{e.preventDefault();card.style.borderTop='3px solid #27845f'});card.addEventListener('dragleave',()=>card.style.borderTop='');card.addEventListener('drop',e=>{e.preventDefault();card.style.borderTop='';const type=e.dataTransfer.getData('text/plain');if(type&&registry[type])addWidget(type,i);else if(dragIndex!==null&&dragIndex!==i){const moved=widgets.splice(dragIndex,1)[0];widgets.splice(i,0,moved);dragIndex=null;render()}});card.querySelector('[data-up]').onclick=()=>move(i,-1);card.querySelector('[data-down]').onclick=()=>move(i,1);card.querySelector('[data-copy]').onclick=()=>{const copy=JSON.parse(JSON.stringify(w));copy.id='w'+Date.now().toString(36);widgets.splice(i+1,0,copy);selected=copy.id;render()};card.querySelector('[data-delete]').onclick=()=>{widgets.splice(i,1);selected=null;render()};root.appendChild(card)});$('pbEmpty').style.display=widgets.length?'none':'block';$('pbCanvasCount').textContent=widgets.length+' widget';$('pbCount').textContent='Sayfada '+widgets.length+' / 80 widget';renderInspector();schedulePreview()}
function move(i,delta){const n=i+delta;if(n<0||n>=widgets.length)return;const a=widgets.splice(i,1)[0];widgets.splice(n,0,a);render()}
function renderInspector(){const root=$('pbInspector'),w=widgets.find(x=>x.id===selected);if(!w){root.className='pb-inspector-empty';root.textContent='Düzenlemek için sayfadaki bir widget’ı seçin.';return}root.className='';const meta=registry[w.type];root.innerHTML='<div class="pb-hint">'+esc(meta.label)+'</div>';const style=document.createElement('label');style.className='pb-field';style.textContent='Widget stili';const select=document.createElement('select');meta.styles.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;o.selected=s===w.style;select.appendChild(o)});select.onchange=()=>{w.style=select.value;render()};style.appendChild(select);root.appendChild(style);fieldsFor(w).forEach(([key,label,type])=>{const f=document.createElement('label');f.className='pb-field';f.textContent=label;let input;if(type==='textarea'){input=document.createElement('textarea')}else if(type==='city'||type==='country'||type==='category'){input=document.createElement('select');const choices=type==='city'?builderCities:(type==='country'?builderCountries:builderCategories);const empty=document.createElement('option');empty.value='';empty.textContent='Tüm konumlar';input.appendChild(empty);choices.forEach(item=>{const o=document.createElement('option');o.value=item.id;o.textContent=item.name;o.selected=String(w.settings?.[key]??'')===String(item.id);input.appendChild(o)})}else if(type.startsWith('select:')){input=document.createElement('select');type.slice(7).split(',').forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=({'1':'Evet','0':'Hayır','overlay':'Görsel üstü','split':'Bölünmüş','minimal':'Minimal','left':'Sol','center':'Orta','right':'Sağ','below':'Hero altında','inside-bottom':'Hero içinde alt kısım','horizontal':'Yatay','vertical':'Dikey'}[v]||v);o.selected=String(w.settings?.[key]??({show_search:'1',hero_layout:'overlay',hero_text_position:'left',search_position:'below',search_layout:'horizontal',alignment:'left'}[key]||''))===v;input.appendChild(o)})}else{input=document.createElement('input');input.type=type;if(type==='number'){input.min=key==='hero_height'?300:(key==='overlay_opacity'?0:1);input.max=key==='hero_height'?900:(key==='overlay_opacity'?90:(key==='columns'?4:(key==='search_columns'?5:24)))}}if(type.startsWith('select:')){const current=w.settings?.[key];input.value=typeof current==='boolean'?(current?'1':'0'):String(current??({show_search:'1',hero_layout:'overlay',hero_text_position:'left',search_position:'below',search_layout:'horizontal',alignment:'left'}[key]||''));}else{input.value=w.settings?.[key]??({hero_height:520,overlay_opacity:55,search_columns:5}[key]??'');}input.addEventListener(type==='city'||type==='country'?'change':'input',()=>{w.settings=w.settings||{};w.settings[key]=type==='number'?Number(input.value):input.value;schedulePreview();const block=Array.from($('pbBlocks').children).find(el=>el.dataset.index===String(widgets.indexOf(w)));if(key==='title'&&block){block.querySelector('.pb-block-title').textContent=input.value;block.querySelector('.pb-block-preview strong').textContent=input.value}});f.appendChild(input);root.appendChild(f)});const note=document.createElement('p');note.className='pb-hint';note.textContent=w.type==='hero'?'Hero görselini, metin hizasını ve arama motorunun hero içindeki veya dışındaki konumunu bağımsız belirleyebilirsiniz.':'Seçtiğiniz widget türüne ait içerik ve yerleşim ayarları burada gösterilir.';root.appendChild(note)}
$('pbCanvas').addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('text/plain'))e.preventDefault()});$('pbCanvas').addEventListener('drop',e=>{const type=e.dataTransfer.getData('text/plain');if(type&&registry[type]&&e.target.closest('#pbCanvas')&&!e.target.closest('.pb-block')){e.preventDefault();addWidget(type)}});$('pbSearch').addEventListener('input',e=>renderPalette(e.target.value));$('pbTheme').onchange=()=>location.href='<?= e(app_url('/admin/builder')) ?>?theme='+encodeURIComponent($('pbTheme').value)+'&page='+encodeURIComponent($('pbPage').value);$('pbPage').onchange=()=>location.href='<?= e(app_url('/admin/builder')) ?>?theme='+encodeURIComponent($('pbTheme').value)+'&page='+encodeURIComponent($('pbPage').value);
document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-device]').forEach(x=>x.classList.toggle('active',x===b));$('pbCanvas').className='pb-canvas device-'+b.dataset.device;$('pbLiveFrame').className='pb-live-frame device-'+b.dataset.device});
$('pbShowPreview').onclick=()=>{ $('pbLiveFrame').style.display='block';$('pbCanvas').style.display='none';$('pbShowPreview').classList.add('active');$('pbShowBlocks').classList.remove('active')};
$('pbShowBlocks').onclick=()=>{ $('pbLiveFrame').style.display='none';$('pbCanvas').style.display='block';$('pbShowBlocks').classList.add('active');$('pbShowPreview').classList.remove('active')};
function submit(status){$('pbFormTheme').value=$('pbTheme').value;$('pbFormPage').value=$('pbPage').value;$('pbFormStatus').value=status;$('pbFormJson').value=JSON.stringify({widgets});$('pbForm').submit()}
$('pbSave').onclick=()=>submit('draft');$('pbPublish').onclick=()=>submit('published');renderPalette();render();
})();
</script></body></html>